CREATE OR REPLACE FUNCTION public.update_fantasy_settings(lid uuid,league_name text,score jsonb,seconds int,lock_time timestamptz DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.league_commissioner(lid) THEN RAISE EXCEPTION 'Only the commissioner can edit settings'; END IF; IF length(trim(league_name)) NOT BETWEEN 2 AND 60 OR seconds NOT BETWEEN 15 AND 180 THEN RAISE EXCEPTION 'Invalid league settings'; END IF; IF NOT (score ?& ARRAY['pts','reb','ast','stl','blk','turnovers']) THEN RAISE EXCEPTION 'All six scoring rules are required'; END IF; IF EXISTS(SELECT 1 FROM jsonb_each_text(score) WHERE value::numeric NOT BETWEEN -10 AND 10) THEN RAISE EXCEPTION 'Scoring values must be between -10 and 10'; END IF; UPDATE leagues SET name=trim(league_name),scoring=score,pick_seconds=seconds,lock_at=lock_time WHERE id=lid; END $$;